import{_ as s,a as n,b as r}from"./chunks/PageInfo.vue_vue_type_script_setup_true_lang.BCVHfIj7.js";import{_ as c,c as d,I as a,a7 as p,o as i}from"./chunks/framework.DGCt2JJv.js";import"./chunks/dayjs.min.DZyl58SH.js";const v=JSON.parse('{"title":"@codesandbox/sandpack-react","description":"","frontmatter":{},"headers":[],"relativePath":"react/React好用的插件/@codesandbox/sandpack-react.md","filePath":"react/React好用的插件/@codesandbox/sandpack-react.md","lastUpdated":1721320892000}'),l={name:"react/React好用的插件/@codesandbox/sandpack-react.md"},h=p('<h1 id="codesandbox-sandpack-react" tabindex="-1">@codesandbox/sandpack-react <a class="header-anchor" href="#codesandbox-sandpack-react" aria-label="Permalink to &quot;@codesandbox/sandpack-react&quot;">​</a></h1><p>Sandpack是在浏览器上运行的实时编码环境。</p><p>Sandpack 是一个组件工具包，用于创建实时运行的代码编辑体验，由 CodeSandbox 上使用的在线捆绑器提供支持。</p><p>沙包|沙袋 -<a href="https://sandpack.codesandbox.io/" target="_blank" rel="noreferrer">https://sandpack.codesandbox.io/</a></p><p>Sanpack 文档 -<a href="https://sandpack.codesandbox.io/docs/" target="_blank" rel="noreferrer">https://sandpack.codesandbox.io/docs/</a></p><p>沙袋 GitHub -<a href="https://github.com/codesandbox/sandpack" target="_blank" rel="noreferrer">https://github.com/codesandbox/sandpack</a></p><p>下一个 MDX 远程 -<a href="https://github.com/hashicorp/next-mdx-remote" target="_blank" rel="noreferrer">https://github.com/hashicorp/next-mdx-remote</a></p><p>所有 MDX 组件 -<a href="https://mdxjs.com/table-of-components/" target="_blank" rel="noreferrer">https://mdxjs.com/table-of-components/</a></p><h2 id="注意版权" tabindex="-1">注意版权 <a class="header-anchor" href="#注意版权" aria-label="Permalink to &quot;注意版权&quot;">​</a></h2><p>Apache 许可证 2.0 属于宽松类别，这意味着你可以用代码（几乎）做任何你想做的事情，只有极少数例外。</p><p>无论您是否修改了代码，您都必须在代码副本中包含以下内容：原始版权声明、许可证副本、已进行重大更改的声明（仅在适用时）以及通知文件的副本。</p><p>对于个人使用，您对如何使用 Sandpack 没有任何限制，无论您是构建私人项目还是公共项目，您都可以自由使用我们所有的模板。</p><p>对于商业用途，您可以自由使用所有 Sandpack 模板，但以下情况除外：</p><ul><li>nextjs, any vite template, astro, node.</li><li>使用 Nodebox 作为运行时环境的任何其他沙盒</li></ul><p>Nodebox 是用于在浏览器中执行Node.js代码的运行时。Sandpack 2.0 使用 Nodebox 直接在浏览器中运行服务器端示例。例如，您可以直接在您的网站上运行 Vite 模板，例如 React 和 Vue。</p><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><ol><li>安装依赖</li></ol><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes light-plus one-dark-pro vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#61AFEF;">pnpm</span><span style="--shiki-light:#A31515;--shiki-dark:#98C379;"> i</span><span style="--shiki-light:#A31515;--shiki-dark:#98C379;"> @codesandbox/sandpack-react</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="contributors" tabindex="-1">Contributors <a class="header-anchor" href="#contributors" aria-label="Permalink to &quot;Contributors&quot;">​</a></h2>',19);function b(k,m,_,u,x,f){const e=s,t=n,o=r;return i(),d("div",null,[h,a(e,{readTime:"1",words:"382"}),a(t),a(o)])}const P=c(l,[["render",b]]);export{v as __pageData,P as default};
